mapper.select:
select cast(id as varchar) as id, event_type, cast(user_id as varchar) as user_id, email, client_ip, reason, occurred_at, consumed_at, kafka_topic, kafka_key, payload_json from audit_logs
event_type = #{eventType}
and user_id = cast(#{userId} as uuid)
and lower(email) = lower(#{email})
order by occurred_at desc, consumed_at desc limit #{limit}
